import java.util.*;class Solution{public List<Integer> countSmaller(int[]a){int[]v=a.clone();Arrays.sort(v);Map<Integer,Integer>rank=new HashMap<>();int z=0;for(int x:v)if(!rank.containsKey(x))rank.put(x,++z);int[]b=new int[z+1],o=new int[a.length];for(int i=a.length-1;i>=0;i--){int r=rank.get(a[i]);for(int x=r-1;x>0;x-=x&-x)o[i]+=b[x];for(int x=r;x<=z;x+=x&-x)b[x]++;}List<Integer>res=new ArrayList<>();for(int x:o)res.add(x);return res;}}
